import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as d}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const M=JSON.parse('{"title":"MiniMax Code 术语表","description":"不教操作。先分清 Code / Agent / Hailuo / 星野，再分清桌面、CLI 和两种模式。","frontmatter":{"title":"MiniMax Code 术语表","description":"不教操作。先分清 Code / Agent / Hailuo / 星野，再分清桌面、CLI 和两种模式。","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"zh/products/minimax-code/minimax-code-glossary.md","filePath":"zh/products/minimax-code/minimax-code-glossary.md","lastUpdated":1787107158000}'),r={name:"zh/products/minimax-code/minimax-code-glossary.md"};function i(n,t,l,c,m,s){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="minimax-code-术语表" tabindex="-1">MiniMax Code 术语表 <a class="header-anchor" href="#minimax-code-术语表" aria-label="Permalink to &quot;MiniMax Code 术语表&quot;">​</a></h1><p>不教操作，只解释这些名字为什么容易撞车。选哪张门看 <a href="./">学习地图</a>。</p><h2 id="都叫-minimax-的东西" tabindex="-1">都叫 MiniMax 的东西 <a class="header-anchor" href="#都叫-minimax-的东西" aria-label="Permalink to &quot;都叫 MiniMax 的东西&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名字</th><th>是什么</th><th>在哪</th></tr></thead><tbody><tr><td><strong>MiniMax Code</strong></td><td>第一方 Coding Agent。桌面应用 + CLI <code>mcode</code></td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">welcome</a>、<a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">download</a>、<a href="https://agent.minimaxi.com/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI</a></td></tr><tr><td>MiniMax Agent</td><td>网页通用 Agent。changelog 里桌面端已更名为 Code，网页产品仍叫 Agent</td><td><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>，本站 #73</td></tr><tr><td>MiniMax Design</td><td>商业内容生产 Agent 平台</td><td><a href="https://design.minimax.io/" target="_blank" rel="noreferrer">design.minimax.io</a></td></tr><tr><td>MiniMax Hub</td><td>中文 About 一级导航仍用的名字</td><td><a href="https://www.minimaxi.com/about" target="_blank" rel="noreferrer">about</a>。与 Design 对账，不另开教程</td></tr><tr><td>MiniMax Audio</td><td>语音与音乐产品</td><td><a href="https://www.minimax.io/audio" target="_blank" rel="noreferrer">minimax.io/audio</a></td></tr><tr><td>Hailuo / 海螺 / MiniMax H3</td><td>视频生成品牌与模型</td><td><a href="https://hailuoai.video/" target="_blank" rel="noreferrer">hailuoai.video</a></td></tr><tr><td>星野</td><td>国内角色互动应用</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">xingyeai.com</a></td></tr><tr><td>Talkie</td><td>国际站 Product 一级里的角色产品</td><td><a href="https://www.minimax.io/" target="_blank" rel="noreferrer">minimax.io</a></td></tr><tr><td>MiniMax M3</td><td>Coding / Agentic 模型，1M 上下文</td><td><a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">models-intro</a></td></tr><tr><td>Token Plan</td><td>开放平台订阅</td><td><a href="https://platform.minimax.io/" target="_blank" rel="noreferrer">platform</a></td></tr><tr><td>通过 AI 编程工具接入</td><td>把 M3 接到 Claude Code / Cursor 等</td><td><a href="https://platform.minimaxi.com/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">text-ai-coding-tools</a></td></tr></tbody></table><p><strong>不要当事实写：</strong></p><ul><li>把 MiniMax Code 写成「只是 M3 的 API 包装」。</li><li>把 <code>minimax</code> 当成 CLI 主命令。官方 CLI 命令是 <code>mcode</code>。changelog v3.0.33 的「minimax 命令行快捷方式」没有独立 flag 页。</li><li>官方 npm 包名。2026-08-19 找不到原文。</li><li>Mini-Agent（<code>MiniMax-AI/Mini-Agent</code>）等于 MiniMax Code。</li><li>官方 VS Code 插件。编辑器集成官方只给了 ACP + Zed 示例。</li></ul><h2 id="一个产品-两张脸" tabindex="-1">一个产品，两张脸 <a class="header-anchor" href="#一个产品-两张脸" aria-label="Permalink to &quot;一个产品，两张脸&quot;">​</a></h2><p>官方：「MiniMax Code CLI 是 MiniMax Code 面向开发者工作流的终端入口。它与桌面客户端互为补充。」</p><table tabindex="0"><thead><tr><th>脸</th><th>入口</th><th>典型用途</th></tr></thead><tbody><tr><td>桌面</td><td>下载页安装包</td><td>图形任务、浏览器、定时任务、Remote Control</td></tr><tr><td>CLI TUI</td><td><code>mcode</code></td><td>人在终端里改仓库</td></tr><tr><td>CLI Headless</td><td><code>mcode exec</code></td><td>CI、脚本</td></tr><tr><td>CLI ACP</td><td><code>mcode acp</code></td><td>嵌进编辑器</td></tr></tbody></table><p>CLI <strong>不依赖</strong>桌面 Electron / IPC。桌面有的 Browser / Computer Use，不能假定 CLI 里一定有。</p><h2 id="模式是两套正交开关" tabindex="-1">模式是两套正交开关 <a class="header-anchor" href="#模式是两套正交开关" aria-label="Permalink to &quot;模式是两套正交开关&quot;">​</a></h2><p>桌面 <strong>Coding / Work</strong>：同一套 Agent，开发工具露多少不同。改仓库用 Coding。</p><p>CLI <strong>Plan Mode</strong>：下一条消息先规划还是直接做。<code>Shift+Tab</code> / <code>/plan</code>。</p><p>CLI <strong>权限模式</strong>：工具要不要问你。<code>Alt+M</code> / <code>/permission</code> → Ask / Auto / Full access。</p><p><code>mcode exec --permission</code> 用 <code>ask</code> / <code>smart</code> / <code>full</code> / <code>off</code>。和 TUI 档名不是同一张枚举，不要合并成一列。</p><h2 id="agent-team" tabindex="-1">Agent Team <a class="header-anchor" href="#agent-team" aria-label="Permalink to &quot;Agent Team&quot;">​</a></h2><p>官方：按任务复杂度引入多个专家 Agent；你只描述目标，产品负责拆解、分配、跟踪、汇总。</p><p>它是 MiniMax Code 里的能力，不是独立产品，也不是网页 MiniMax Agent。</p><h2 id="工作区、技能、记忆" tabindex="-1">工作区、技能、记忆 <a class="header-anchor" href="#工作区、技能、记忆" aria-label="Permalink to &quot;工作区、技能、记忆&quot;">​</a></h2><ul><li><strong>工作区</strong>：本地项目目录。Agent 在该目录内读文件、跑命令、汇报变更。</li><li><strong>技能</strong>：可复用工作流。输入框可用 <code>/</code> 调用（桌面第一次任务页）。</li><li><strong>记忆</strong>：沉淀偏好、项目约定、长期经验（桌面文档树有独立页）。</li><li><strong><code>AGENTS.md</code></strong>：<code>mcode init</code> 会生成或更新的项目指导。</li></ul><h2 id="账号与额度" tabindex="-1">账号与额度 <a class="header-anchor" href="#账号与额度" aria-label="Permalink to &quot;账号与额度&quot;">​</a></h2><p>MiniMax 账号登录桌面或 <code>mcode login</code>。自备 MiniMax API Key 走产品内设置或 <code>mcode provider</code>。</p><p>Token Plan 是开放平台订阅；M3 博文写 Code 可以用 Token Plan。下载页 Plus / Max / Ultra 与 Token Plan 美元档不要当成同一价目。用量页：「具体计费和额度规则以产品内展示为准。」</p>',23)])])}const f=e(r,[["render",i]]);export{M as __pageData,f as default};
